<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); ?><header class="site-head"><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><span class="tl-logo-badge"><img src="https://odpc.de/wp-content/uploads/2026/02/FB_IMG_1771601697384.jpg" alt="Café Tante Lenchen" width="160" height="160"><svg viewBox="0 0 200 200" aria-hidden="true"><defs><path id="tl-logo-head" d="M 17,110 A 83,83 0 1,1 183,110"/></defs><text><textPath href="#tl-logo-head" startOffset="50%" text-anchor="middle">Café Tante Lenchen</textPath></text></svg></span><span>Café Tante Lenchen</span></a><button class="tl-menu-toggle" type="button" aria-expanded="false" aria-controls="tl-main-nav" aria-label="Navigation öffnen"><span class="tl-menu-icon" aria-hidden="true">☰</span><span class="tl-menu-toggle-label">Menü</span></button><nav id="tl-main-nav" class="nav" aria-label="Hauptnavigation"><?php foreach(['Startseite'=>'','Speisekarte'=>'speisekarte','Tisch anfragen'=>'tisch-anfragen','Kontakt'=>'kontakt','Anfahrt'=>'anfahrt','Galerie'=>'galerie','Medien & Presse'=>'medien','Impressum'=>'impressum','Datenschutz'=>'datenschutz'] as $label=>$slug){$p=$slug?get_page_by_path($slug):null;if(in_array($slug,['impressum','datenschutz'],true)&&(!$p||$p->post_status!=='publish'))continue;echo '<a href="'.esc_url(home_url('/'.($slug?$slug.'/':''))).'">'.esc_html($label).'</a>';} ?></nav><script>(function(){function init(){var b=document.querySelector('.tl-menu-toggle'),n=document.getElementById('tl-main-nav');if(!b||!n)return;b.addEventListener('click',function(){var open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Navigation schließen':'Navigation öffnen');b.querySelector('.tl-menu-icon').textContent=open?'✕':'☰';b.querySelector('.tl-menu-toggle-label').textContent=open?'Schließen':'Menü';n.classList.toggle('tl-nav-open',open)});document.addEventListener('keydown',function(e){if(e.key==='Escape'){b.setAttribute('aria-expanded','false');n.classList.remove('tl-nav-open');b.querySelector('.tl-menu-icon').textContent='☰';b.querySelector('.tl-menu-toggle-label').textContent='Menü'}})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();</script></header><main class="wrap">